BEGIN;
DO $$
DECLARE
  updates jsonb := '{"topic-1":"<h4>Watch and apply</h4><div><a href=\"https://www.cfp.net/ethics/compliance-resources/2020/06/the-duty-to-disclose-material-conflicts-of-interest-when-responding\" target=\"_blank\" rel=\"noopener noreferrer\">Disclosing material conflicts</a> · CFP Board<p>Identify the material conflict and explain how the advisor should disclose and manage it.</p></div>","topic-7":"<h4>Watch and apply</h4><div><a href=\"https://www.cfp.net/ethics/compliance-resources/2021/01/case-study--financial-advice-that-requires-financial-planning\" target=\"_blank\" rel=\"noopener noreferrer\">When advice requires financial planning</a> · CFP Board<p>Identify which areas the recommendation affects and what that means for the scope of work.</p></div>","topic-9":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=9_NiqI3RAOA\" target=\"_blank\" rel=\"noopener noreferrer\">Budgeting basics</a> · Federal Trade Commission<p>Turn one annual bill into a monthly reserve and explain where it belongs in cash flow.</p></div>","topic-12":"<h4>Watch and apply</h4><div><a href=\"https://www.khanacademy.org/science/core-finance/interest-tutorial/present-value/v/introduction-to-present-value\" target=\"_blank\" rel=\"noopener noreferrer\">Introduction to present value</a> · Khan Academy<p>Calculate what $25,000 due in five years is worth today at 4%. Explain what changes when the discount rate rises.</p></div>","topic-14":"<h4>Watch and apply</h4><div><a href=\"https://www.invesco.com/education-savings/en/collegebound-529-investor/resources/529-videos.html\" target=\"_blank\" rel=\"noopener noreferrer\">529 education savings videos</a> · Invesco<p>Use the sponsor’s examples to identify the account owner and beneficiary. Verify current rules independently before applying them.</p></div>","topic-19":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=t13f66cLHVQ&amp;t=123s\" target=\"_blank\" rel=\"noopener noreferrer\">How to shop for a health insurance plan</a> · Texas Department of Insurance<p>Explain why a lower premium can produce a higher annual cost. Compare networks and out-of-pocket exposure.</p></div>","topic-23":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=iw1GQRSZNZw\" target=\"_blank\" rel=\"noopener noreferrer\">Understanding universal life</a> · Texas Department of Insurance<p>Name two items you would verify in an in-force policy illustration when reviewing a policy’s funding.</p></div>","topic-31":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=MZchH0Ddzn8&amp;t=173s\" target=\"_blank\" rel=\"noopener noreferrer\">What is diversification?</a> · Fidelity<p>Explain why owning two funds that hold the same securities may add little diversification.</p></div>","topic-32":"<h4>Watch and apply</h4><div><a href=\"https://www.khanacademy.org/economics-finance-domain/core-finance/stock-and-bonds/bonds-tutorial/v/relationship-between-bond-prices-and-interest-rates\" target=\"_blank\" rel=\"noopener noreferrer\">Why bond prices and interest rates move in opposite directions</a> · Khan Academy<p>Explain why an existing bond’s fixed coupon becomes less attractive when new bonds offer higher yields.</p></div>","topic-37":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=eMxTgPtpvmE\" target=\"_blank\" rel=\"noopener noreferrer\">Estimated tax payments</a> · IRS<p>Explain how estimated payments fit into paying tax during the year and which facts you would check with a tax professional.</p></div>","topic-38":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=qPtQcdAuFj4\" target=\"_blank\" rel=\"noopener noreferrer\">Corporations: Raising capital and distributing profits</a> · IRS<p>Explain where a C corporation’s tax can arise and how a shareholder distribution differs from wages.</p></div>","topic-45":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=MlNw4LovNjE\" target=\"_blank\" rel=\"noopener noreferrer\">The parts of Medicare</a> · CMS<p>Match Parts A, B, C and D to their roles. Explain how that comparison differs from deciding when to claim Social Security.</p></div>","topic-48":"<h4>Watch and apply</h4><div><a href=\"https://www.cfp.net/ethics/compliance-resources/2019/10/applying-the-code-and-standards-to-a-rollover-recommendation\" target=\"_blank\" rel=\"noopener noreferrer\">Applying the fiduciary standard to a rollover recommendation</a> · CFP Board<p>List three facts you would compare before recommending a rollover. Include at least one reason to leave assets in the employer plan.</p></div>","topic-54":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=vfp2dCNHvXE\" target=\"_blank\" rel=\"noopener noreferrer\">Property ownership forms</a> · Oklahoma State University Extension<p>Compare how survivorship ownership and tenancy in common can change what passes at death. Verify local law.</p></div>","topic-56":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=QKuxaxm9ubY\" target=\"_blank\" rel=\"noopener noreferrer\">Critical estate planning documents</a> · Oklahoma State University Extension<p>Explain which documents address incapacity and which direct the disposition of probate property. Verify execution rules in the client’s state.</p></div>","topic-59":"<h4>Watch and apply</h4><div><a href=\"https://www.youtube.com/watch?v=u2HyNhAJkmo\" target=\"_blank\" rel=\"noopener noreferrer\">Trusts</a> · Oklahoma State University Extension<p>Identify grantor, trustee and beneficiary, and explain why funding matters. Verify state-specific terms with counsel.</p></div>","start":"<h4>Video library</h4><p>Choose <strong>Watch and discuss</strong> in the lesson menu for all videos. Related lessons also have a <strong>Watch and apply</strong> section.</p>"}'::jsonb;
  existing jsonb;
BEGIN
  SELECT lessons INTO STRICT existing FROM public.tac_academy_courses
    WHERE slug = 'financial-planning-cfp-prep' FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(updates || '{"video":""}'::jsonb) AS ids(id)
    WHERE (SELECT count(*) FROM jsonb_array_elements(existing) AS l WHERE l->>'id' = ids.id) <> 1
  ) THEN
    RAISE EXCEPTION 'CFP prep lesson targets do not match the current course';
  END IF;

  UPDATE public.tac_academy_courses
  SET lessons = (
    SELECT jsonb_agg(
      CASE
        WHEN l->>'id' = 'video' THEN jsonb_set(l, '{html}', to_jsonb('<h3>Watch and discuss</h3><p>Watch each video with its lesson. Pause before the example finishes, solve it yourself, then answer the prompt in your own words. Verify current rules and thresholds against official sources, especially for taxes, benefits and state law.</p><h4>Ethics and the planning process</h4><ul><li>Topic 1 · <a href="https://www.cfp.net/ethics/compliance-resources/2020/06/the-duty-to-disclose-material-conflicts-of-interest-when-responding" target="_blank" rel="noopener noreferrer">Disclosing material conflicts</a> · CFP Board<p>Identify the material conflict and explain how the advisor should disclose and manage it.</p></li><li>Topic 7 · <a href="https://www.cfp.net/ethics/compliance-resources/2021/01/case-study--financial-advice-that-requires-financial-planning" target="_blank" rel="noopener noreferrer">When advice requires financial planning</a> · CFP Board<p>Identify which areas the recommendation affects and what that means for the scope of work.</p></li><li>Topic 9 · <a href="https://www.youtube.com/watch?v=9_NiqI3RAOA" target="_blank" rel="noopener noreferrer">Budgeting basics</a> · Federal Trade Commission<p>Turn one annual bill into a monthly reserve and explain where it belongs in cash flow.</p></li><li>Topic 12 · <a href="https://www.khanacademy.org/science/core-finance/interest-tutorial/present-value/v/introduction-to-present-value" target="_blank" rel="noopener noreferrer">Introduction to present value</a> · Khan Academy<p>Calculate what $25,000 due in five years is worth today at 4%. Explain what changes when the discount rate rises.</p></li><li>Topic 14 · <a href="https://www.invesco.com/education-savings/en/collegebound-529-investor/resources/529-videos.html" target="_blank" rel="noopener noreferrer">529 education savings videos</a> · Invesco<p>Use the sponsor’s examples to identify the account owner and beneficiary. Verify current rules independently before applying them.</p></li></ul><h4>Insurance and benefits</h4><ul><li>Topic 19 · <a href="https://www.youtube.com/watch?v=t13f66cLHVQ&amp;t=123s" target="_blank" rel="noopener noreferrer">How to shop for a health insurance plan</a> · Texas Department of Insurance<p>Explain why a lower premium can produce a higher annual cost. Compare networks and out-of-pocket exposure.</p></li><li>Topic 23 · <a href="https://www.youtube.com/watch?v=iw1GQRSZNZw" target="_blank" rel="noopener noreferrer">Understanding universal life</a> · Texas Department of Insurance<p>Name two items you would verify in an in-force policy illustration when reviewing a policy’s funding.</p></li></ul><h4>Investments</h4><ul><li>Topic 31 · <a href="https://www.youtube.com/watch?v=MZchH0Ddzn8&amp;t=173s" target="_blank" rel="noopener noreferrer">What is diversification?</a> · Fidelity<p>Explain why owning two funds that hold the same securities may add little diversification.</p></li><li>Topic 32 · <a href="https://www.khanacademy.org/economics-finance-domain/core-finance/stock-and-bonds/bonds-tutorial/v/relationship-between-bond-prices-and-interest-rates" target="_blank" rel="noopener noreferrer">Why bond prices and interest rates move in opposite directions</a> · Khan Academy<p>Explain why an existing bond’s fixed coupon becomes less attractive when new bonds offer higher yields.</p></li></ul><h4>Tax planning</h4><ul><li>Topic 37 · <a href="https://www.youtube.com/watch?v=eMxTgPtpvmE" target="_blank" rel="noopener noreferrer">Estimated tax payments</a> · IRS<p>Explain how estimated payments fit into paying tax during the year and which facts you would check with a tax professional.</p></li><li>Topic 38 · <a href="https://www.youtube.com/watch?v=qPtQcdAuFj4" target="_blank" rel="noopener noreferrer">Corporations: Raising capital and distributing profits</a> · IRS<p>Explain where a C corporation’s tax can arise and how a shareholder distribution differs from wages.</p></li></ul><h4>Retirement planning</h4><ul><li>Topic 45 · <a href="https://www.youtube.com/watch?v=MlNw4LovNjE" target="_blank" rel="noopener noreferrer">The parts of Medicare</a> · CMS<p>Match Parts A, B, C and D to their roles. Explain how that comparison differs from deciding when to claim Social Security.</p></li><li>Topic 48 · <a href="https://www.cfp.net/ethics/compliance-resources/2019/10/applying-the-code-and-standards-to-a-rollover-recommendation" target="_blank" rel="noopener noreferrer">Applying the fiduciary standard to a rollover recommendation</a> · CFP Board<p>List three facts you would compare before recommending a rollover. Include at least one reason to leave assets in the employer plan.</p></li></ul><h4>Estate planning</h4><ul><li>Topic 54 · <a href="https://www.youtube.com/watch?v=vfp2dCNHvXE" target="_blank" rel="noopener noreferrer">Property ownership forms</a> · Oklahoma State University Extension<p>Compare how survivorship ownership and tenancy in common can change what passes at death. Verify local law.</p></li><li>Topic 56 · <a href="https://www.youtube.com/watch?v=QKuxaxm9ubY" target="_blank" rel="noopener noreferrer">Critical estate planning documents</a> · Oklahoma State University Extension<p>Explain which documents address incapacity and which direct the disposition of probate property. Verify execution rules in the client’s state.</p></li><li>Topic 59 · <a href="https://www.youtube.com/watch?v=u2HyNhAJkmo" target="_blank" rel="noopener noreferrer">Trusts</a> · Oklahoma State University Extension<p>Identify grantor, trustee and beneficiary, and explain why funding matters. Verify state-specific terms with counsel.</p></li></ul><p><a href="https://www.cfp.net/-/media/files/cfp-board/standards-and-ethics/compliance-resources/guide-to-financial-planning-process.pdf" target="_blank" rel="noopener noreferrer">CFP Board guide to the financial planning process</a> · Compare your case memo with the guide’s example.</p>'::text))
        WHEN updates ? (l->>'id') AND strpos(l->>'html', updates->>(l->>'id')) = 0
          THEN jsonb_set(l, '{html}', to_jsonb((l->>'html') || (updates->>(l->>'id'))))
        ELSE l
      END ORDER BY ord
    )
    FROM jsonb_array_elements(existing) WITH ORDINALITY AS seq(l, ord)
  )
  WHERE slug = 'financial-planning-cfp-prep';
END;
$$;
COMMIT;
